import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import '../styles/Contacto.css';

const Contacto = () => {
  const [form, setForm] = useState({ nombre: '', email: '', mensaje: '' });
  const [enviado, setEnviado] = useState(false);
  const navigate = useNavigate();
  useEffect(() => {
    document.body.style.backgroundImage = "url('/fondo-naranja.png')";
    document.body.style.backgroundPosition = "center";
    document.body.style.backgroundSize = "cover";
    document.body.style.backgroundRepeat = "no-repeat";
    document.body.style.minHeight = "100vh";
    return () => {
      document.body.style.backgroundImage = "";
      document.body.style.backgroundPosition = "";
      document.body.style.backgroundSize = "";
      document.body.style.backgroundRepeat = "";
      document.body.style.minHeight = "";
    };
  }, []);

  const handleChange = e => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  const handleSubmit = async e => {
    e.preventDefault();
    await fetch('http://localhost:4000/api/contacto', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(form)
    });
    setEnviado(true);
  };

  return (
    <div className="contacto-container">
      <button onClick={() => navigate(-1)} className="servicios-btn" style={{marginBottom: '1.5rem'}}>
        Regresar
      </button>
      <h2 className="contacto-title">Contacto</h2>
      {enviado ? <p className="contacto-msg">¡Gracias por contactarnos! Pronto te responderemos.</p> : (
        <form className="contacto-form" onSubmit={handleSubmit}>
          <input name="nombre" placeholder="Nombre" value={form.nombre} onChange={handleChange} required />
          <input name="email" type="email" placeholder="Email" value={form.email} onChange={handleChange} required />
          <textarea name="mensaje" placeholder="Mensaje" value={form.mensaje} onChange={handleChange} required />
          <button type="submit">Enviar</button>
        </form>
      )}
    </div>
  );
};

export default Contacto;
